//! Offline PCM16 WAV processing and streaming DSP.
use std::{fs,path::Path};
#[derive(Clone,Copy,Debug,PartialEq,serde::Serialize,serde::Deserialize)] #[serde(default)] pub struct WavEffects{pub low_db:f32,pub high_db:f32,pub room:f32,pub reverb:f32}
impl Default for WavEffects{fn default()->Self{Self{low_db:0.,high_db:0.,room:0.,reverb:0.}}}
fn u16_at(b:&[u8],i:usize)->u16{u16::from_le_bytes([b[i],b[i+1]])}
fn u32_at(b:&[u8],i:usize)->u32{u32::from_le_bytes([b[i],b[i+1],b[i+2],b[i+3]])}
/// Two-band crossover at 1 kHz plus three decaying early-reflection taps.
pub fn process_pcm16_wav(input:&[u8],fx:WavEffects)->Result<Vec<u8>,String>{
 if fx.reverb!=0.{return Err("Reverb is streaming-only; set reverb to zero for offline WAV export".into());}if input.len()<12||input.len()>32*1024*1024||&input[..4]!=b"RIFF"||&input[8..12]!=b"WAVE"{return Err("Expected PCM16 RIFF WAV, max 32 MiB".into());}
 let mut fmt=None;let mut data=None;let mut at=12;while at+8<=input.len(){let len=u32_at(input,at+4) as usize;let start=at+8;let end=start.checked_add(len).ok_or("Invalid WAV chunk")?;if end>input.len(){return Err("Truncated WAV chunk".into());}match &input[at..at+4]{b"fmt " if len>=16=>fmt=Some(&input[start..end]),b"data"=>data=Some(start..end),_=>{}}at=end+(len&1);}
 let fmt=fmt.ok_or("Missing WAV format")?;let data=data.ok_or("Missing WAV data")?;let channels=u16_at(fmt,2) as usize;let rate=u32_at(fmt,4) as usize;if u16_at(fmt,0)!=1||!(1..=2).contains(&channels)||u16_at(fmt,14)!=16||u16_at(fmt,12) as usize!=2*channels||!(8000..=96000).contains(&rate)||data.len()%(2*channels)!=0{return Err("Only mono/stereo PCM16 WAV, 8–96 kHz".into());}
 if ![fx.low_db,fx.high_db,fx.room].iter().all(|v|v.is_finite()){return Err("Invalid effects parameters".into());}let mut out=input.to_vec();let low=10_f32.powf(fx.low_db.clamp(-12.,12.)/20.);let high=10_f32.powf(fx.high_db.clamp(-12.,12.)/20.);let room=fx.room.clamp(0.,1.);let coeff=1.-(-std::f32::consts::TAU*1000./rate as f32).exp();let samples:Vec<f32>=input[data.clone()].chunks_exact(2).map(|x|i16::from_le_bytes([x[0],x[1]]) as f32/32768.).collect();let mut filter=[0.;2];let mut dry=vec![0.;samples.len()];for (i,&x) in samples.iter().enumerate(){let c=i%channels;filter[c]+=coeff*(x-filter[c]);dry[i]=low*filter[c]+high*(x-filter[c]);}
 let taps=[(rate*37/1000*channels,0.24_f32),(rate*73/1000*channels,0.15_f32),(rate*113/1000*channels,0.09_f32)];for i in 0..dry.len(){let mut y=dry[i];for (delay,gain) in taps{if i>=delay{y+=room*gain*dry[i-delay];}}let v=(y*32768.).round().clamp(-32768.,32767.) as i16;let j=data.start+i*2;out[j..j+2].copy_from_slice(&v.to_le_bytes());}Ok(out)
}
pub fn render_wav_effects(source:&Path,root:&Path,fx:WavEffects)->Result<String,String>{let size=fs::metadata(source).map_err(|e|e.to_string())?.len();if size>32*1024*1024{return Err("WAV max 32 MiB".into());}let input=fs::read(source).map_err(|e|e.to_string())?;let output=process_pcm16_wav(&input,fx)?;let rel=format!("assets/fx-{}.wav",uuid::Uuid::new_v4());fs::create_dir_all(root.join("assets")).map_err(|e|e.to_string())?;fs::write(root.join(&rel),output).map_err(|e|e.to_string())?;Ok(rel)}
#[cfg(test)]mod tests{use super::*;#[test]fn rejects_invalid(){assert!(process_pcm16_wav(b"bad",Default::default()).is_err());}#[test]fn unity_preserves_samples(){let mut b=b"RIFF".to_vec();b.extend_from_slice(&40u32.to_le_bytes());b.extend_from_slice(b"WAVEfmt ");b.extend_from_slice(&16u32.to_le_bytes());b.extend_from_slice(&1u16.to_le_bytes());b.extend_from_slice(&1u16.to_le_bytes());b.extend_from_slice(&8000u32.to_le_bytes());b.extend_from_slice(&16000u32.to_le_bytes());b.extend_from_slice(&2u16.to_le_bytes());b.extend_from_slice(&16u16.to_le_bytes());b.extend_from_slice(b"data");b.extend_from_slice(&4u32.to_le_bytes());b.extend_from_slice(&1234i16.to_le_bytes());b.extend_from_slice(&(-1000i16).to_le_bytes());assert_eq!(process_pcm16_wav(&b,Default::default()).unwrap(),b);}}

/// Stateful streaming DSP core. Allocate once at construction; process arbitrary interleaved blocks
/// with the same history. This is not yet attached to Bevy's audio callback.
pub struct StreamingEffects{channels:usize,coeff:f32,low:[f32;2],history:Vec<f32>,cursor:usize,channel:usize,taps:[usize;3],gain_low:f32,gain_high:f32,room:f32,target:[f32;3],smoothing:f32,reverb:f32,reverb_target:f32,comb:[Vec<f32>;4],comb_pos:[usize;4],damp:[[f32;2];4]}
impl StreamingEffects{
 pub fn new(rate:u32,channels:usize,fx:WavEffects)->Result<Self,String>{if !(8000..=96000).contains(&rate)||!(1..=2).contains(&channels){return Err("Unsupported DSP format".into());}let taps=[37,73,113].map(|ms|rate as usize*ms/1000*channels);let mut s=Self{channels,coeff:1.-(-std::f32::consts::TAU*1000./rate as f32).exp(),low:[0.;2],history:vec![0.;taps[2]+channels],cursor:0,channel:0,taps,gain_low:1.,gain_high:1.,room:0.,target:[1.,1.,0.],smoothing:1.-(-1./(rate as f32*0.020)).exp(),reverb:0.,reverb_target:0.,comb:[29,41,53,67].map(|ms|vec![0.;(rate as usize*ms/1000)*channels]),comb_pos:[0;4],damp:[[0.;2];4]};s.set_effects(fx)?;[s.gain_low,s.gain_high,s.room]=s.target;s.reverb=s.reverb_target;Ok(s)}
 pub fn set_effects(&mut self,fx:WavEffects)->Result<(),String>{if ![fx.low_db,fx.high_db,fx.room].iter().all(|v|v.is_finite()){return Err("Invalid DSP settings".into());}if !fx.reverb.is_finite(){return Err("Invalid reverb".into());}self.reverb_target=fx.reverb.clamp(0.,1.);self.target=[10_f32.powf(fx.low_db.clamp(-12.,12.)/20.),10_f32.powf(fx.high_db.clamp(-12.,12.)/20.),fx.room.clamp(0.,1.)];Ok(())}
 pub fn process(&mut self,samples:&mut [f32]){self.process_inner(samples,true);}
 pub fn process_unclipped(&mut self,samples:&mut [f32]){self.process_inner(samples,false);}
 fn process_inner(&mut self,samples:&mut [f32],clip:bool){let n=self.history.len();for x in samples{let input=if x.is_finite(){*x}else{0.};let c=self.channel;if c==0{self.gain_low+=(self.target[0]-self.gain_low)*self.smoothing;self.gain_high+=(self.target[1]-self.gain_high)*self.smoothing;self.room+=(self.target[2]-self.room)*self.smoothing;self.reverb+=(self.reverb_target-self.reverb)*self.smoothing;}self.low[c]+=self.coeff*(input-self.low[c]);let dry=if self.gain_low==1.&&self.gain_high==1.{input}else{self.gain_low*self.low[c]+self.gain_high*(input-self.low[c])};let mut out=dry;for (delay,gain) in self.taps.into_iter().zip([0.24,0.15,0.09]){out+=self.room*gain*self.history[(self.cursor+n-delay)%n];}let mut wet=0.;for i in 0..4{let j=self.comb_pos[i];let delayed=self.comb[i][j];self.damp[i][c]+=0.28*(delayed-self.damp[i][c]);self.comb[i][j]=dry+0.68*self.damp[i][c];self.comb_pos[i]=(j+1)%self.comb[i].len();wet+=delayed;}out+=self.reverb*0.25*wet;self.history[self.cursor]=dry+self.room*0.35*self.history[(self.cursor+n-self.taps[2])%n];self.cursor=(self.cursor+1)%n;self.channel=(c+1)%self.channels;*x=if !out.is_finite(){0.}else if clip{out.clamp(-1.,1.)}else{out.clamp(-64.,64.)};}}
}
#[cfg(test)]mod streaming_tests{use super::*;#[test]fn chunk_continuity_and_stereo(){let fx=WavEffects{low_db:2.,high_db:-1.,room:0.7,reverb:0.};let mut a=vec![0.;2400];a[0]=0.5;let mut b=a.clone();let mut one=StreamingEffects::new(8000,2,fx).unwrap();let mut split=StreamingEffects::new(8000,2,fx).unwrap();one.process(&mut a);for c in b.chunks_mut(137){split.process(c);}assert_eq!(a,b);assert!(a.iter().skip(1).step_by(2).all(|v|*v==0.));assert!(a[592].abs()>0.001);}}

/// Built-in source presets; existing Master/Music/SFX routing stays intact.
pub const DSP_PRESETS:[(&str,WavEffects);5]=[
 ("Flat",WavEffects{low_db:0.,high_db:0.,room:0.,reverb:0.}),
 ("Warm",WavEffects{low_db:4.,high_db:-3.,room:0.1,reverb:0.}),
 ("Bright",WavEffects{low_db:-2.,high_db:5.,room:0.05,reverb:0.}),
 ("Small room",WavEffects{low_db:0.,high_db:-1.,room:0.35,reverb:0.}),
 ("Large room",WavEffects{low_db:1.,high_db:-4.,room:0.85,reverb:0.35})];
#[cfg(test)]mod smoothing_tests{use super::*;#[test]fn smooth_and_stereo(){let mut dsp=StreamingEffects::new(8000,2,Default::default()).unwrap();dsp.set_effects(DSP_PRESETS[1].1).unwrap();let mut a=[0.25;2];dsp.process(&mut a);assert_eq!(a[0],a[1]);assert!((a[0]-0.25).abs()<0.01);assert!(dsp.gain_low>1.&&dsp.gain_low<dsp.target[0]);let mut b=vec![0.;16000];dsp.process(&mut b);assert!((dsp.gain_low-dsp.target[0]).abs()<0.001);}}


#[cfg(test)]mod reverb29{use super::*;#[test]fn impulse_tail_stereo(){let mut dry=StreamingEffects::new(8000,2,Default::default()).unwrap();let mut wet=StreamingEffects::new(8000,2,WavEffects{reverb:0.7,..Default::default()}).unwrap();let mut a=vec![0.;8000];a[0]=0.4;let mut b=a.clone();dry.process(&mut a);wet.process(&mut b);assert!(a[1..].iter().all(|v|v.abs()<1e-6));assert!(b[2..].iter().any(|v|v.abs()>0.001));assert!(b.iter().skip(1).step_by(2).all(|v|*v==0.));}}


/// Shared DSP after summing synchronized PCM blocks. No allocation in process_block.
pub struct SummedBus { effects:StreamingEffects, channels:usize }
impl SummedBus {
 pub fn new(rate:u32,channels:usize,fx:WavEffects)->Result<Self,String>{Ok(Self{effects:StreamingEffects::new(rate,channels,fx)?,channels})}
 pub fn set_effects(&mut self,fx:WavEffects)->Result<(),String>{self.effects.set_effects(fx)}
 pub fn process_block(&mut self,inputs:&[(&[f32],f32)],out:&mut [f32])->Result<(),String>{
  if inputs.len()>16||out.len()%self.channels!=0||inputs.iter().any(|(s,g)|s.len()!=out.len()||!g.is_finite()||!(0. ..=1.).contains(g)){return Err("Invalid aligned PCM blocks or gains".into());}
  out.fill(0.);for (samples,gain) in inputs{for (dst,x) in out.iter_mut().zip(*samples){if x.is_finite(){*dst+=(*x).clamp(-1.,1.) * *gain;}}}self.effects.process(out);Ok(())
 }
}
/// Offline common-bus export: aligned mono/stereo PCM16 files of identical format; shorter tracks are silent after EOF.
pub fn mix_bus_wavs(inputs:&[Vec<u8>],fx:WavEffects)->Result<Vec<u8>,String>{
 if inputs.is_empty()||inputs.len()>16||inputs.iter().map(Vec::len).sum::<usize>()>32*1024*1024{return Err("Choose 1–16 WAV files, total <=32 MiB".into());}
 fn parse(b:&[u8])->Result<(u32,usize,&[u8]),String>{if b.len()<12||&b[..4]!=b"RIFF"||&b[8..12]!=b"WAVE"{return Err("Invalid WAV".into());}let(mut fmt,mut data)=(None,None);let mut pos=12;while pos+8<=b.len(){let n=u32_at(b,pos+4) as usize;let a=pos+8;let end=a.checked_add(n).ok_or("WAV overflow")?;if end>b.len(){return Err("Truncated WAV".into());}match &b[pos..pos+4]{b"fmt " if n>=16=>fmt=Some(&b[a..end]),b"data"=>data=Some(&b[a..end]),_=>{}}pos=end+(n&1);}let f=fmt.ok_or("Missing format")?;let d=data.ok_or("Missing PCM")?;let c=u16_at(f,2) as usize;let r=u32_at(f,4);if u16_at(f,0)!=1||!(1..=2).contains(&c)||u16_at(f,14)!=16||u16_at(f,12) as usize!=c*2||!(8000..=96000).contains(&r)||d.len()%(c*2)!=0{return Err("PCM16 mono/stereo 8–96 kHz required".into());}Ok((r,c,d))}
 let parsed=inputs.iter().map(|b|parse(b)).collect::<Result<Vec<_>,_>>()?;let(rate,ch,_)=parsed[0];if parsed.iter().any(|(r,c,_)|*r!=rate||*c!=ch){return Err("All tracks must have identical sample rate and channel count".into());}let samples=parsed.iter().map(|(_,_,b)|b.len()/2).max().unwrap_or(0);let tail=if fx.reverb>0.||fx.room>0.{rate as usize*ch*2}else{0};let count=samples+tail;let mut bus=SummedBus::new(rate,ch,fx)?;let mut output=Vec::with_capacity(44+count*2);output.extend_from_slice(b"RIFF");output.extend_from_slice(&(36+count as u32*2).to_le_bytes());output.extend_from_slice(b"WAVEfmt ");output.extend_from_slice(&16u32.to_le_bytes());output.extend_from_slice(&1u16.to_le_bytes());output.extend_from_slice(&(ch as u16).to_le_bytes());output.extend_from_slice(&rate.to_le_bytes());output.extend_from_slice(&(rate*ch as u32*2).to_le_bytes());output.extend_from_slice(&(ch as u16*2).to_le_bytes());output.extend_from_slice(&16u16.to_le_bytes());output.extend_from_slice(b"data");output.extend_from_slice(&(count as u32*2).to_le_bytes());
 let mut mixed=[0_f32;512];let mut processed=[0_f32;512];let gain=1./parsed.len() as f32;for start in (0..count).step_by(512){let n=(count-start).min(512);mixed[..n].fill(0.);for (_,_,data) in &parsed{for (i,x) in mixed[..n].iter_mut().enumerate(){let at=(start+i)*2;if at+2<=data.len(){*x+=i16::from_le_bytes([data[at],data[at+1]]) as f32/32768.*gain;}}}bus.process_block(&[(&mixed[..n],1.)],&mut processed[..n])?;for x in &processed[..n]{output.extend_from_slice(&((*x*32768.).round().clamp(-32768.,32767.) as i16).to_le_bytes());}}Ok(output)
}
#[cfg(test)]mod summed34{use super::*;#[test]fn sum_before_effects_and_validate(){let mut bus=SummedBus::new(8000,1,Default::default()).unwrap();let mut out=[0.;2];bus.process_block(&[(&[0.2,0.4],0.5),(&[0.4,-0.2],0.5)],&mut out).unwrap();assert!((out[0]-0.3).abs()<1e-6);assert!((out[1]-0.1).abs()<1e-6);assert!(bus.process_block(&[(&[0.],1.)],&mut out).is_err());}}
